"""Interactive, browser-local calculation models with visible assumptions."""

def field(ident,label,value,minimum=0,maximum=None,step=1):
    return f'<label for="{ident}">{label}<input type="number" id="{ident}" value="{value}" min="{minimum}"'+(f' max="{maximum}"' if maximum is not None else '')+f' step="{step}"></label>'

def lab(ident,title,controls,assumption):
    return f'<section class="lab extra-lab" id="lab-{ident}" data-model="{ident}"><span class="eyebrow">THE WORKBENCH · CALCULATED TEACHING MODEL</span><h3>{title}</h3><div class="lab-controls">{controls}</div><div class="lab-output" id="model-{ident}-result" aria-live="polite"></div><p class="assumption">{assumption}</p><noscript><p>The adjacent prose, formulas, and original figures show the worked values without JavaScript. This calculator changes only local model inputs.</p></noscript></section>'

BENCHES={
2:lab('capacity','Size the assumed social workload',field('model-users','Daily active users',10000000)+field('model-requests','API requests per user/day',50)+field('model-peak','Peak multiplier',5,1,100,.5)+field('model-rps','Assumed tested RPS per instance',600,1)+field('model-utilization','Target utilization fraction',.6,.01,.99,.01),'Decimal units. Assumed image views: 10 × 200 kB/user/day; posts: 1 × 2 kB/user/day. Per-instance capacity is an input, not an atlas benchmark. Database and failure-domain feasibility need independent evidence.'),
4:lab('queue','A bigger queue cannot repair a permanent rate mismatch',field('model-arrivals','Arrival rate jobs/s',150)+field('model-service','Completion capacity jobs/s',100)+field('model-duration','Duration seconds',60)+field('model-buffer','Waiting queue limit jobs',100),'Fluid approximation with constant rates and initially empty waiting queue. The model accounts for completed, waiting, and rejected work; real scheduling, startup, and per-job variance are omitted.'),
10:lab('ticket','Replay the last-seat interleaving','<label for="model-ticket-policy">Claim policy<select id="model-ticket-policy"><option value="naive">Read then unprotected write</option><option value="conditional">Atomic conditional claim</option></select></label>','Deterministic two-caller interleaving, not a production transaction engine. The executable SQLite fixture verifies the local conditional-update invariant separately.'),
11:lab('lru','Inspect exact LRU state after each access','<label for="model-cache-access">Access sequence, comma separated<input id="model-cache-access" value="A,B,C,A,D" maxlength="200"></label>'+field('model-cache-capacity','Cache entries',3,1,20),'Ideal entry-count LRU; each access loads or refreshes a key. Real engines may approximate eviction and have byte-size and expiration policies. No source freshness guarantee follows.'),
12:lab('hash','Compare owners before and after adding D',field('model-hash-key','Selected integer key',190,0,1000000),'Deterministic illustrative rendezvous scores. Stable assignment is not data transfer, membership agreement, traffic balance, or protection against one hot key.'),
13:lab('pipeline','Reject stale or deleted workflow completion','<label for="model-pipeline-scenario">Attempt scenario<select id="model-pipeline-scenario"><option value="stale">Epoch 7 completes after epoch 8 owns run</option><option value="wrong">Current epoch uses old input version F1</option><option value="valid">Current epoch 8 uses source F2</option><option value="deleted">Document was deleted before completion</option></select></label>','One local conditional-transition model. Persisting and applying the condition atomically is required in a real store. External model calls and object writes are outside this local transition.'),
14:lab('quorum','Inspect fixed-set quorum intersection',field('model-quorum-n','Replica count N',3,1,9)+field('model-quorum-r','Read set size R',2,1,9)+field('model-quorum-w','Write set size W',2,1,9),'Only set intersection is calculated. Membership, version rules, concurrent writes, persistence, and repair determine the actual consistency protocol. R + W > N alone does not prove linearizability.'),
21:lab('cost','Compare cost per useful outcome',field('model-outcomes','Successful outcomes/month',150000,1),'Fictional monthly totals: single 371, replicated application 551, partitioned 1402. Capacity, p99, availability, and invariant feasibility are not established by these totals. This is not live provider pricing.')}
BUCKET=lab('bucket','Spend a bounded burst, then advance time','<div class="lab-actions"><button type="button" id="model-bucket-spend">Spend one token</button><button type="button" id="model-bucket-advance">Advance 3 seconds</button><button type="button" id="model-bucket-reset">Reset</button></div>','Capacity ten, refill two tokens per second, one local owner, virtual monotonic time. A real shared bucket needs an atomic transition; distributed global admission requires an explicit protocol.')
